// data/mages-content.js — Wikipedia-grounded bios + works profile per mage, keyed by name.
// Render merges this into MAGES by name. Bios are 2-3 paragraphs (\n\n separated);
// works is a table of {title, note}. Sourced from en.wikipedia.org summaries.
const MAGES_CONTENT = {
  "Solomon": { wikipediaUrl: "https://en.wikipedia.org/wiki/Solomon", bio: "Solomon (also called Jedidiah) was, per the Hebrew Bible, a king of ancient Israel who succeeded his father David and reigned c. 970\u2013931 BCE over a united Israel and Judah. Born in Jerusalem to David and Bathsheba, he is credited with building the First Temple and a royal palace complex, forging trade alliances with Hiram I of Tyre, and presiding over a period of reported commercial prosperity. He died around age 55 after a 40-year reign, and his son Rehoboam's succession was followed by the schism of the kingdom into Israel (north) and Judah (south).\n\nThe biblical portrait emphasizes Solomon's legendary wisdom: when offered anything by God he asked for wisdom, the Judgement of Solomon is his best-known display of it, and the Queen of Sheba is said to have visited to test his fame. His accumulation of 700 wives and 300 concubines\u2014many foreign\u2014and his wealth, horses, and idolatrous influences are presented as leading to divine displeasure. The historicity of Solomon is hotly debated: most scholars think he probably existed, but the biblical description of his empire's lavishness is widely regarded as an anachronistic exaggeration, with maximalist and minimalist scholars differing on how much can be recovered.\n\nBeyond the canon, a vast pseudepigraphical and occult corpus attached itself to Solomon in Jewish, Islamic, and Western esoteric tradition. Rabbinic literature describes him commanding demons, spirits, and animals by means of a signet ring\u2014the Seal of Solomon\u2014often depicted as a pentagram or hexagram and considered the predecessor of the Star of David. Medieval grimoires and demonological texts (the Testament of Solomon, the Key of Solomon, the Lemegeton) made Solomon the archetypal magician-sovereign who binds and interrogates spirits, a motif that fed Jewish mysticism, Sufi parallels, and Renaissance occultism.", works: [{"title": "Proverbs (Mishlei)", "note": "Wisdom maxims attributed to Solomon; shaped later Hebrew stellar-letter sapiential tradition."}, {"title": "Ecclesiastes (Kohelet)", "note": "Book on time and vanity; its time-cycles later informed kabbalistic chronosophy."}, {"title": "Song of Songs (Shir ha-Shirim)", "note": "Allegorical poetry; central to kabbalistic mystical reading of divine-human union."}, {"title": "Key of Solomon (Clavicula Salomonis)", "note": "Medieval grimoire: seals, planetary talismans, and spirit-binding rituals."}, {"title": "Lesser Key of Solomon (Lemegeton)", "note": "Renaissance grimoire casting Solomon as demon-binder; lists 72 spirits in the Ars Goetia."}] },
  "Hermes Trismegistus": { wikipediaUrl: "https://en.wikipedia.org/wiki/Hermes_Trismegistus", bio: "Hermes Trismegistus (\"Thrice-Greatest Hermes\") is a legendary Hellenistic figure arising from the syncretic fusion of the Greek god Hermes and the Egyptian god Thoth, worshiped as one at the Temple of Thoth in Khemenu (Hermopolis) in the Ptolemaic period. The epithet \"thrice great\" likely derives from an Egyptian temple inscription \"Thoth the great, the great, the great,\" with the earliest datable occurrence in minutes of a 172 BCE Ibis-cult council meeting near Memphis. He is not a historical person but the eponym of a body of Greco-Egyptian religious-philosophical texts.\n\nThe Hermetic writings are divided into philosophical hermetica (cosmology and theology) and technical hermetica (practical magic, alchemy, astrology). Their actual authorship is by various unknown Greek authors working roughly in the 2nd\u20133rd century CE, blending Platonism, Stoicism, Jewish, and Persian influences; Isaac Casaubon demonstrated in 1614 that they postdate Christianity, collapsing the Renaissance belief in their extreme antiquity. During the Renaissance Marsilio Ficino translated the Corpus Hermeticum into Latin, and figures such as Lactantius, Augustine, Pico della Mirandola, and Giordano Bruno revered Hermes as a wise pagan prophet who foresaw Christianity within a prisca theologia threading through all religions.\n\nIn Islamic hagiography Hermes was identified with the prophet Idris (equated with Enoch), and Abu Ma'shar al-Balkhi described a threefold Hermes as civilizing hero, initiator of Pythagoras, and first teacher of alchemy. Hermes was strongly associated with astrology, and the Hermetic tradition came to encompass alchemy, magic, astrology, and related subjects; later offshoots include Hermetic Qabalah, the Hermetic Order of the Golden Dawn, and Rosicrucianism, making Hermes the foundational eponym of Western esotericism.", works: [{"title": "Corpus Hermeticum", "note": "Core Greco-Egyptian religious-philosophical treatises; foundation of Hermetic cosmology and prisca theologia."}, {"title": "Poimandres", "note": "First treatise of the Corpus; divine-revelation cosmogony underpinning Hermetic stellar-letter cosmology."}, {"title": "Emerald Tablet (Tabula Smaragdina)", "note": "Alchemical text bearing the maxim 'as above, so below'—key to Hermetic stellar correspondence."}, {"title": "Asclepius", "note": "Latin dialogue on theology and cosmic worship; influential in Renaissance magic and astrological talismanry."}, {"title": "Centiloquium Hermetis", "note": "Medieval astrological aphorisms attributed to Hermes; shaped Islamic and Latin stellar-letter astrology."}] },
  "Zoroaster": { wikipediaUrl: "https://en.wikipedia.org/wiki/Zoroaster", bio: "Zoroaster (Avestan Zara\u03b8u\u0161tra; Greek Zoroaster; Persian Zartosht), of the Spitama family and son of Pourushaspa, was an ancient Iranian priest-prophet traditionally dated c. 628\u2013551 BCE, though modern scholarship is divided between a \"late date\" (7th\u20136th century BCE) and an \"early date\" (c. 1500\u20131000 BCE), the latter increasingly favored on linguistic grounds from the Old Avestan of the Gathas. His birthplace is unknown, with proposed locations including Bactria, Sistan, Chorasmia, and the steppes west of the Volga; classical and medieval sources also placed him in Media or Azerbaijan. Per tradition he trained as a priest from age seven, left his parents at twenty, and at thirty received a revelation in which Vohu Manah (Good Purpose) led him to Ahura Mazda and the radiant Amesha Spentas.\n\nZoroaster's teaching centers on the cosmic dualism of a\u0161a (truth, order) versus druj (deception), embodied in the opposition of Ahura Mazda (Wise Lord) and Angra Mainyu (Destructive Spirit), with human free will and ethical responsibility\u2014good thoughts, words, and deeds\u2014as the means of aligning with a\u0161a and hastening frashokereti, the ultimate renovation of existence. Around age 42 he gained the patronage of King Vishtaspa and Queen Hutaosa, married three times, fathered six children, and is said to have died at 77, with conflicting traditions of murder by a priest of the old religion or by a Turanian soldier. He is traditionally credited with authoring the Gathas and the Yasna Haptanghaiti, the core Old Avestan hymns of the Avesta.\n\nIn classical antiquity Zoroaster was associated with astrology and magic: Pliny the Elder named him the inventor of magic, and Diogenes Laertius linked his name with star-worship (astrothytes, 'star sacrificer'). A large pseudepigraphic Hellenistic corpus\u2014On Nature, the Asteroskopita astrological handbook, On the Virtue of Stones, and the Coptic Zostrianos\u2014circulated under his name from the 3rd century BCE onward, works Roger Beck noted were Hellenistic creations borrowing his authority rather than expressions of Zoroastrian doctrine. His influence extended to Judaism, Christianity, Manichaeism (which counted him among four primary prophets), and the Bah\u00e1'\u00ed Faith, which recognizes him as a Manifestation of God.", works: [{"title": "The Gathas", "note": "Old Avestan hymns traditionally authored by Zoroaster; core statement of dualism, aša, and Amesha Spentas."}, {"title": "Yasna Haptanghaiti", "note": "Seven-chapter Old Avestan liturgical hymn cycle; foundational Zoroastrian worship text."}, {"title": "Asteroskopita (Apotelesmatika)", "note": "Pseudepigraphic astrological handbook under Zoroaster's name; Hellenistic stellar-letter lore."}, {"title": "On the Virtue of Stones (Peri lithon timion)", "note": "Pseudepigraphic lapidary; talismanic stone-lore feeding later occultism."}, {"title": "Zostrianos", "note": "Coptic Gnostic tractate at Nag Hammadi bearing his name; stellar-revelation framing in Gnosticism."}] },
  "Daniel": { wikipediaUrl: "https://en.wikipedia.org/wiki/Daniel_(biblical_figure)", bio: "Daniel (Hebrew \u05d3\u05b8\u05bc\u05e0\u05b4\u05d9\u05b5\u05bc\u05d0\u05dc, \"God is my Judge\") was, according to tradition, a noble Jewish youth of Jerusalem taken into Babylonian captivity by Nebuchadnezzar II (traditionally c. 620\u2013538 BCE) and given the Babylonian name Belteshazzar. He served the Babylonian and Persian courts with loyalty and ability until the time of the Persian conqueror Cyrus, refusing royal food to avoid defilement alongside his companions Hananiah, Mishael, and Azariah. The court tales (Daniel 1\u20136) credit him with interpreting Nebuchadnezzar's dreams of a four-metal statue and a great felled tree, reading the mysterious writing on the wall at Belshazzar's feast, and surviving the lions' den through angelic deliverance.\n\nThe apocalyptic visions (Daniel 7\u201312) describe four beasts from the sea, a ram-and-goat conflict, a final struggle of king of the north versus king of the south, and the vindication of the righteous, all mediated by the angel Gabriel as interpreter. These visions introduced or crystallized several key esoteric numerological schemes: the \"70 weeks/sevens\" of years (Daniel 9), the \"2300 evenings and mornings\" (Daniel 8:14), and \"a time, times, and half a time\" (Daniel 7:25; 12:7), widely read as cryptic references to the persecution under Antiochus IV Epiphanes (r. 175\u2013164 BCE). Daniel is one of the earliest biblical texts to feature a named angelic mediator, making it a hinge of later apocalyptic and esoteric angelology.\n\nScholarly consensus regards Daniel as a non-historical or only partly historical figure whose book was composed in stages: the court tales in the 3rd or early 2nd century BCE, and the visions added between 167 and 164 BCE as cryptic allusions to Antiochus IV. In Judaism Daniel is not classed among the prophets (prophecy being held to have ended with Haggai, Zechariah, and Malachi) but is placed among the Writings and called the most distinguished member of the Babylonian diaspora; Christianity honors him as a prophet, the New Testament citing the \"abomination of desolation\" at Matthew 24:15; Islam does not name him in the Qur'an but Shia tradition affirms him as a prophet, and the Bah\u00e1'\u00ed Faith regards him as a minor prophet.", works: [{"title": "Book of Daniel (chapters 1–12)", "note": "Court tales + apocalyptic visions; source of 70-weeks and 'time, times, half a time' numerology."}, {"title": "Susanna (Daniel 13, Greek)", "note": "Deuterocanonical addition: Daniel saves Susanna by cross-examining two elders."}, {"title": "Bel and the Dragon (Daniel 14, Greek)", "note": "Deuterocanonical: Daniel exposes idol-priests and a sacred serpent; Habakkuk feeds him by miracle."}, {"title": "Prayer of Azariah (Daniel 3, Greek)", "note": "Deuterocanonical expansion of the fiery furnace; Azariah's prayer within the flames."}, {"title": "Song of the Three Holy Children (Daniel 3, Greek)", "note": "Deuterocanonical canticle of the three youths; used in Christian liturgy (Benedicite)."}] },
  "Shadrach (Hananiah)": { wikipediaUrl: "https://en.wikipedia.org/wiki/Shadrach,_Meshach,_and_Abednego", bio: "Shadrach (Hebrew \u05d7\u05b2\u05e0\u05b7\u05e0\u05b0\u05d9\u05b8\u05d4 Hananiah, \"Yah is gracious\"; Babylonian \u05e9\u05b7\u05c1\u05d3\u05b0\u05e8\u05b7\u05da Shadrach, likely reflecting \"\u0160udur Aku,\" \"Command of Aku [the moon god]\") was, per the Book of Daniel, a Jewish youth taken from Jerusalem to Babylon during the reign of Nebuchadnezzar II (r. 605\u2013562 BCE), placing him in the late 7th or early 6th century BCE. Alongside his companions Mishael (Meshach) and Azariah (Abednego), and together with Daniel, he was selected for training in the Chaldean Aramaic language and literature for service at the royal court, where his Hebrew name was replaced with a Babylonian theophoric one substituting the moon-god Aku for Yah (Daniel 1).\n\nShadrach's principal narrative is the fiery furnace episode (Daniel 3): Nebuchadnezzar erected a golden image on the plain of Dura\u2014its dimensions of 6 by 60 cubits carrying symbolic contrast with the 60-by-60 Second Temple of Ezra\u2013Nehemiah\u2014and commanded all officials to worship it. Hananiah, Mishael, and Azariah refused, telling the king the question was not their willingness but whether God was present and able to save; the furnace was heated seven times hotter than normal, yet the king saw four figures walking unharmed in the flames, \"the fourth... like a son of God.\" Emerging with hair unsinged, cloaks undamaged, and no smell of fire, they were promoted to high office. Daniel is absent from this chapter, which scholars suggest may originally have been an independent tale.\n\nThe deuterocanonical Prayer of Azariah and Song of the Three Holy Children, preserved in the Greek Septuagint but absent from the Hebrew/Aramaic Masoretic text, expand the furnace episode with Azariah's penitential prayer and the three youths' canticle of all creation. The Song (Benedicite) entered Christian liturgy as an alternative to the Te Deum in Anglican Morning Prayer and as the Lauds canticle for Sundays and feasts in the Roman rite; the Byzantine and Lutheran churches commemorate the three alongside Daniel on December 17. Claimed tombs of Hananiah and Azariah are venerated in the Mosque of the Prophet Daniel in the Kirkuk Citadel, northern Iraq.", works: [{"title": "Daniel 1 (court introduction)", "note": "Hananiah→Shadrach name-change; theonym-substitution stellar-letter pattern (Yah→Aku)."}, {"title": "Daniel 3 (fiery furnace narrative)", "note": "Core account of the trio's refusal and the fourth figure in the flames; martyrdom/rescue typology."}, {"title": "Song of the Three Holy Children (Benedicite)", "note": "Deuterocanonical canticle; cosmic-liturgical 'all creation bless the Lord' hymn."}, {"title": "Prayer of Azariah", "note": "Deuterocanonical penitential prayer within the furnace; paired with the Song in Septuagint Daniel 3."}] },
  "Meshach (Mishael)": { wikipediaUrl: "https://en.wikipedia.org/wiki/Shadrach,_Meshach,_and_Abednego", bio: "Meshach (Hebrew \u05de\u05b4\u05d9\u05e9\u05b8\u05c1\u05d0\u05b5\u05dc Mishael, \"Who is what El is?\"; Babylonian \u05de\u05b5\u05d9\u05e9\u05b7\u05c1\u05da\u05b0 Meshach, likely \"Who is as Aku is?\") was, per the Book of Daniel, a Jewish youth taken from Jerusalem to Babylon during the reign of Nebuchadnezzar II (r. 605\u2013562 BCE), placing him in the late 7th or early 6th century BCE. With his companions Hananiah (Shadrach) and Azariah (Abednego), and together with Daniel, he was selected for training in the Chaldean Aramaic language and literature for royal service, where his Hebrew theophoric name\u2014invoking El\u2014was replaced by a Babylonian one invoking the moon-god Aku (Daniel 1). Like the others, he refused the royal food to avoid defilement.\n\nMeshach figures centrally in the fiery furnace episode (Daniel 3): Nebuchadnezzar erected a golden image on the plain of Dura\u2014its 6-by-60-cubit dimensions carrying symbolic contrast with the 60-by-60 Second Temple\u2014and commanded all officials to worship it. Mishael, Hananiah, and Azariah refused, declaring the issue was not their willingness but whether God was able to deliver; cast into a furnace heated seven times beyond normal, they were seen walking unharmed with a fourth figure \"like a son of God,\" and emerged without singed hair, scorched cloaks, or smell of fire. They were then promoted to high office; Daniel's absence from the chapter leads scholars to suggest the story may have circulated independently before incorporation into the book.\n\nThe deuterocanonical Prayer of Azariah and Song of the Three Holy Children, preserved in the Greek Septuagint but absent from the Hebrew/Aramaic Masoretic text, expand the furnace episode with a penitential prayer and a cosmic canticle sung by the three youths. The Song (Benedicite) entered Christian liturgy as an alternative to the Te Deum in Anglican Morning Prayer and as the Sunday and feast-day Lauds canticle in the Roman rite; Byzantine and Lutheran calendars commemorate the three with Daniel on December 17. A claimed tomb of Mishael is not firmly identified, though claimed tombs of Hananiah and Azariah are venerated in the Mosque of the Prophet Daniel in the Kirkuk Citadel, northern Iraq.", works: [{"title": "Daniel 1 (court introduction)", "note": "Mishael→Meshach name-change; theonym-substitution stellar-letter pattern (El→Aku)."}, {"title": "Daniel 3 (fiery furnace narrative)", "note": "Core account of the trio's refusal and the fourth figure in the flames; martyrdom/rescue typology."}, {"title": "Song of the Three Holy Children (Benedicite)", "note": "Deuterocanonical canticle; cosmic-liturgical 'all creation bless the Lord' hymn."}, {"title": "Prayer of Azariah", "note": "Deuterocanonical penitential prayer within the furnace; paired with the Song in Septuagint Daniel 3."}] },
  "Abednego (Azariah)": { wikipediaUrl: "https://en.wikipedia.org/wiki/Shadrach,_Meshach,_and_Abednego", bio: "Abednego is the Babylonian name given to Azariah (\u05e2\u05b2\u05d6\u05b7\u05e8\u05b0\u05d9\u05b8\u05d4, \"Yah has helped\"), one of three young Judeans taken into Babylonian royal service in the Book of Daniel. His Babylonian name likely means \"slave of the god Nebo/Nabu\" (or possibly Nergal), replacing the theonym \"Yah\" with a Babylonian god's name. Along with Hananiah (Shadrach) and Mishael (Meshach), he was selected for training in Chaldean Aramaic language and literature at the Babylonian court.\n\nThe trio's defining narrative is the fiery furnace in Daniel 3: refusing Nebuchadnezzar II's command to worship a golden image on the plain of Dura, they were cast into a furnace heated \"seven times hotter than normal\" yet emerged unharmed. Nebuchadnezzar saw a fourth figure \"like a son of God\" in the flames and promoted the three to high office. Abednego's faithfulness under Babylonian idolatry made him an enduring exemplar of Jewish resistance to assimilation.\n\nThe stories in Daniel 1\u20136 originate among the Jewish community in Babylon and Mesopotamia during the Persian and early Hellenistic periods (5th\u20133rd centuries BCE). Abednego is honored in Jewish, Christian (deuterocanonical Prayer of Azariah), and Islamic traditions, with feast days varying across rites. Though the Wikipedia article notes no explicit kabbalistic or stellar significance, the Babylonian context and theophoric substitution of Yah for Nabu/Nergal situates him within the Mesopotamian astral-religious milieu that later fed esoteric letter-name traditions.", works: [{"title": "Daniel 3 (Fiery Furnace narrative)", "note": "Core account of Abednego's refusal of idolatry and miraculous deliverance; name-substitution motif."}, {"title": "Prayer of Azariah and Song of the Three Holy Children", "note": "Deuterocanonical: gives Azariah a first-person prayer; links Babylonian exile to Hebrew invocation."}, {"title": "Daniel 1 (Induction into Babylon)", "note": "Records Azariah→Abednego renaming; central to theophoric/letter-substitution esoteric readings."}] },
  "The Magi of Matthew 2": { wikipediaUrl: "https://en.wikipedia.org/wiki/Biblical_Magi", bio: "The Magi (singular magus, from Old Persian magu\u0161, rooted in Avestan priestly caste) are \"distinguished foreigners\" who visit the infant Jesus in Matthew 2, bearing gold, frankincense, and myrrh. The Gospel provides no names, exact number, or social status; the familiar count of three derives from the three gifts, while Syriac Christianity often numbers twelve. Matthew only states they came \"from the east,\" with the Parthian Empire (centered in Persia/Iran) as the likely cultural context.\n\nAs Zoroastrian priests, the Magi \"paid particular attention to the stars and gained an international reputation for astrology,\" then regarded as a science; several Bible translations render magoi as \"astrologers.\" Historian Anders Hultg\u00e5rd concluded the Matthean narrative was influenced by an Iranian legend of magi and a star predicting a ruler's birth, and Sebastian Brock traced magi legends to converts from Zoroastrianism. The star of Bethlehem has been variously theorized as a 5 BC comet (Colin Humphreys, drawing on Chinese records) or a 7 BC triple conjunction of Jupiter and Saturn in Pisces.\n\nWestern traditional names Melchior, Caspar, and Balthazar first appear in the 8th-century Excerpta Latina Barbari. The Magi are commemorated on Epiphany (January 6), and their Zoroastrian-astrological origin made derivatives of \"magi\" a byword for the occult. Their stellar-following narrative is the New Testament's clearest link between astral observation and sacred revelation, situating them as archetypal reader-of-the-sky figures for later kabbalistic and occult letter-star systems.", works: [{"title": "Gospel of Matthew 2", "note": "Primary source: magi follow a star to Bethlehem; sole NT link of astral observation to revelation."}, {"title": "Excerpta Latina Barbari (8th c.)", "note": "Earliest source naming Melchior, Caspar, Balthazar; fixed the three-magus star-magic tradition."}, {"title": "Revelation of the Magi (Syriac)", "note": "Apocryphon casting magi as Seth's descendants receiving a star-revelation; astral-mystical reading."}, {"title": "John of Hildesheim, Historia Trium Regum (14th c.)", "note": "Medieval compendium of magi legends and Helena's relic recovery; standardized Western magi-star lore."}] },
  "Abraham ibn Ezra": { wikipediaUrl: "https://en.wikipedia.org/wiki/Abraham_ibn_Ezra", bio: "Abraham ben Meir Ibn Ezra (c. 1089\u20131167) was born in Tudela, Navarre, and became one of medieval Jewry's most versatile scholars, working across biblical exegesis, Hebrew grammar, poetry, mathematics, astronomy, and astrology. A close friend of Judah Halevi, he spent three decades wandering after 1137, reaching Baghdad, Italy, France, and England. His four children died young; his son Isaac converted to Islam in 1140, a wound that troubled him for years.\n\nHis biblical commentaries adhere to the literal sense (peshat), avoiding rabbinic allegory and kabbalistic interpretation, yet exercise rationalist criticism\u2014famously flagging passages implying non-Mosaic authorship of the Torah, later cited by Spinoza. He was among the first to propose dividing Isaiah into at least two parts on chronological grounds. In grammar, works like Sefer Moznayim (1140) and Tzakhoot (1145) systematized Hebrew linguistic science, while Sefer ha-Ekhad and Yesod Mispar treated the peculiarities of numbers and numerals.\n\nIbn Ezra's astrology is the strongest stellar-letter dimension of his oeuvre: in B\u00e9ziers (1147\u201348) he composed a systematic seven-book astrology series (Reshit Hokhma, Sefer ha-Te'amim, Sefer ha-Moladot, Sefer ha-Me'orot, Sefer ha-She'elot, Sefer ha-Mivharim, Sefer ha-Olam), and wrote Mishpetai ha-Mazzelot (\"Judgments of the Zodiacal Signs\"). His Neoplatonic-flavored philosophy gave astrology a recognized place, and his numerical and zodiacal writings feed directly into the mazzalot/letter-correspondence traditions. A lunar crater, Abenezra, is named after him.", works: [{"title": "Mishpetai ha-Mazzelot (Judgments of the Zodiacal Signs)", "note": "First astrology book; zodiacal signs and judgments—core stellar-letter source for mazzalot."}, {"title": "Reshit Hokhma (The Beginning of Wisdom)", "note": "Intro to astrology opening his 7-book Béziers series; Arabic zodiacal science into Hebrew stellar lore."}, {"title": "Sefer ha-Ekhad / Yesod Mispar", "note": "Peculiarities of numbers 1–9; bridges gematria-style numerology with the Indo-Arab numeral system."}, {"title": "Keli ha-Nechoshet (On the Astrolabe)", "note": "Hebrew treatise on the astrolabe; ties stellar observation to calendrical/letter computations."}, {"title": "Pentateuch Commentary (Sefer ha-Yashar)", "note": "Literalist Torah exegesis; numbered-letter observations later supplied gematria-aware readings."}] },
  "Michael Scot": { wikipediaUrl: "https://en.wikipedia.org/wiki/Michael_Scot", bio: "Michael Scot (c. 1175\u2013c. 1232/34) was born in the Scottish border region and trained broadly at Durham, Oxford, and Paris in philosophy, mathematics, astrology, and theology, becoming an ordained priest. He traveled to Bologna, Palermo, and Toledo, where he learned Arabic well enough to translate Aristotle and the commentaries of Averroes into Latin, alongside original works of Avicenna. Scot became \"a typical example of the polyglot wandering scholar of the Middle Ages\u2014 a churchman who knew Latin, Greek, Arabic and Hebrew.\"\n\nAround age 50 he entered the court of Holy Roman Emperor Frederick II in Sicily, serving as science adviser and court astrologer and supervising fresh Arabic-to-Latin translations of Aristotle's Historia animalium, De anima, and De caelo with Averroes's commentaries. Frederick's 1227 letter queried him on \"the foundations of the earth, the geography and rulership of the heavens\" and the locations of hell, purgatory, and paradise; the chronicler Fra Salimbene records Frederick trying to trick Scot by lowering a church tower. Pope Gregory IX offered him Canterbury, which he declined.\n\nScot's own writings\u2014Liber introductorius (a divination trilogy), Super auctorem spherae (commentary on Sacrobosco's Sphere), De sole et luna (alchemy treating sun and moon as images of gold and silver), and De chiromantia\u2014made his popular reputation as a magician, fixed by Dante in Inferno XX among sorcerers and astrologers. His Hebrew knowledge alongside Arabic-Latin occult/astrological transmission places him within the medieval esoteric stream where celestial-letter correspondences circulated. Fibonacci's second-edition Liber Abaci (1227) was dedicated to him.", works: [{"title": "Liber introductorius (incl. Liber physiognomiae)", "note": "Divination trilogy on astronomy, cosmology, physiognomy; transmits Arabic celestial-mantic science."}, {"title": "Super auctorem spherae", "note": "Commentary on Sacrobosco's Sphere at Frederick II's request; core medieval celestial-sphere treatise."}, {"title": "De sole et luna (On the Sun and Moon)", "note": "Alchemical work: sun and moon as images of gold and silver; fuses astral bodies with metal-letter symbolism."}, {"title": "Translations of Aristotle + Averroes (De caelo, De anima)", "note": "Arabic-to-Latin translations transmitting Islamic celestial philosophy; later medieval star-letter theory."}] },
  "Roger Bacon": { wikipediaUrl: "https://en.wikipedia.org/wiki/Roger_Bacon", bio: "Roger Bacon (c. 1219/20\u2013c. 1292) was born near Ilchester, Somerset, and studied at Oxford, where Robert Grosseteste's legacy influenced him, before teaching at the University of Paris from around 1237, lecturing on grammar, logic, arithmetic, geometry, and the mathematical aspects of astronomy and music. He became a Franciscan friar around 1256\u201357 and thereafter faced statutes restricting friars' publication, which he experienced as enforced scholarly absence. His title Doctor Mirabilis was posthumous.\n\nWhen his acquaintance Guy de Foulques became Pope Clement IV in 1265, Bacon was commissioned to write on reform of the medieval curriculum and sent, in 1267\u201368, the Opus Majus plus Opus Minus, De Multiplicatione Specierum, and De Speculis Comburentibus\u2014roughly a million words in a year, an effort called one of the most remarkable single efforts of literary productivity. After Clement's death (1268) and the Condemnations of 1277 (which banned deterministic astrology), Bacon was apparently imprisoned or placed under house arrest, possibly linked to his interest in astrological doctrines and contemporary prophecies; the first record of imprisonment dates eighty years after his death.\n\nBacon's Opus Majus covered mathematics, optics (perspectiva, drawn largely from Alhazen), alchemy, and astronomy-astrology, and proposed a Julian-calendar reform prefiguring the Gregorian system. He cited the Corpus Hermeticum and the Emerald Tablet via his edition of the Secretum Secretorum, considered alchemy the most important science, and held that Sapientia (Divine Wisdom) could be logically explained with tangible evidence. His universal-grammar claim\u2014\"Grammar is one and the same in all languages, substantially\"\u2014and his stress on Arabic, Greek, Hebrew, and Latin situate him in the multilingual esoteric milieu where celestial influence and letter-science intersect.", works: [{"title": "Opus Majus (1267)", "note": "Encyclopedic reform treatise: math, optics, alchemy, astrology; fused celestial science with reform."}, {"title": "De Multiplicatione Specierum", "note": "Theory of propagation of species/powers through media; underpins his optics and astral-influence metaphysics."}, {"title": "Edition of Secretum Secretorum", "note": "Latin edition of Arabic Sirr al-ʿasrar; Hermetic/esoteric lore attributed to Aristotle; shaped his astrology."}, {"title": "Grammatica Hebraica", "note": "Hebrew contrastive grammar for Latin readers; places Hebrew letter-science in his esoteric program."}, {"title": "Opus Minus / Opus Tertium", "note": "Summaries/companions to Opus Majus; further expose his calendrical-reform and celestial-influence arguments."}] },
  "Alfonso X of Castile": { wikipediaUrl: "https://en.wikipedia.org/wiki/Alfonso_X_of_Castile", bio: "Alfonso X (1221\u20131284), nicknamed \"the Wise\" (el Sabio) and \"the Astrologer\" (el Astr\u00f3logo), was born in Toledo, eldest son of Ferdinand III, and succeeded as King of Castile, Le\u00f3n, and Galicia in 1252. He opened his reign with military campaigns in the Algarve and alliances with England, then pursued a costly, ultimately failed bid for the German crown (1257\u20131275), debasing coinage and alienating burghers. His final years were consumed by civil war with his son Sancho over the succession; he died defeated at Seville on 4 April 1284.\n\nAs a lawmaker he produced the Fuero Real and the Siete Partidas, \"one of medieval Europe's most comprehensive law codes,\" which still underlies law in the American Southwest. In 1273 he created the Mesta, a sheepholders' association that made wool Castile's first major export but later harmed the agrarian economy. He is one of 23 lawmakers depicted in the U.S. Capitol's House chamber.\n\nAlfonso's defining legacy is his court culture: continuing the Toledo School of Translators, he employed Jewish, Christian, and Muslim scholars\u2014 notably the Jewish astronomer Yehuda ben Moshe\u2014to translate Arabic and Hebrew learning into Castilian, establishing the foundations of the Spanish language. His most significant scientific achievement was the Alfonsine tables (based on al-Zarqali's calculations), the most influential astronomical tables of the late Middle Ages. Early in his reign he commissioned translations of astral-magic works (Lapidario, Picatrix, Libro de las formas et las ymagenes) and astrological compendia (Libro de las cruzes, Libro conplido en los iudizios de las estrellas), placing his court at the center of medieval star-magic and talismanic-letter transmission.", works: [{"title": "Alfonsine Tables", "note": "Astronomical/astrological tables based on al-Zarqali; most influential late-medieval star tables."}, {"title": "Lapidario", "note": "Magical/astrological properties of stones by Yehuda ben Moshe; star-stone talismanic correspondences."}, {"title": "Picatrix (Castilian translation)", "note": "Arabic astral-magic treatise rendered at Alfonso's court; key conduit for talismanic letter-magic."}, {"title": "Libro conplido en los iudizios de las estrellas", "note": "Arabic astrological compendium on judgments of the stars; foundational to stellar-letter theory."}, {"title": "Siete Partidas", "note": "Comprehensive law code; \"one of medieval Europe's most comprehensive,\" still law in SW US."}] },
  "Ramon Llull": { wikipediaUrl: "https://en.wikipedia.org/wiki/Ramon_Llull", bio: "Ramon Llull (c. 1232\u20131316) was a Catalan philosopher, mystic, and poet born in Palma de Mallorca in the Kingdom of Majorca, into a wealthy family of Barcelona patricians who had arrived with the conquering armies of James I of Aragon. Before his religious conversion he lived the worldly life of a troubadour, but after a series of five visions of Christ on the Cross in 1263 he sold his possessions on the model of Saint Francis of Assisi and joined the Third Order of Saint Francis, dedicating himself to converting Muslims and writing against the errors of unbelievers. He spent roughly nine years in solitude studying Latin and Arabic, even purchasing a Muslim slave to learn Arabic directly.\n\nLlull's central contribution was his Art (Ars), a universal combinatorial logic designed to prove Christian doctrine to people of all faiths through a set of general principles activated in a combinatorial process illustrated with diagrams and letters. The system evolved through a quaternary phase (1274\u20131290), represented by the Ars demonstrativa with sixteen divine principles, and a ternary phase (1290\u20131308) culminating in the Ars generalis ultima and its abridgment the Ars brevis. He introduced the doctrine of \"correlatives,\" a threefold structure of agent, patient, and act underlying all being, which he used to attempt proofs of the Trinity and Incarnation, and urged the creation of language schools for missionary training, an advocacy that helped prompt the Council of Vienne (1311) to order chairs of Hebrew, Arabic, and Aramaic at several universities.\n\nAlthough Llull was a Christian theologian rather than a kabbalist, his Art's mechanical, algorithmic character resembles the Arabic zairja device used by medieval Arab astrologers and parallels contemplation of the ninety-nine Names of God in Islam, and the system prefigured computation theory, later influencing Leibniz's De Arte Combinatoria. A substantial body of alchemical treatises, including the Testamentum and Liber de secretis naturae seu de quinta essentia, was falsely attributed to him in the fourteenth century, and occultists such as Agrippa and Giordano Bruno drew on these pseudo-Lullian works. He was beatified by Pope Pius IX in 1847, and modern scholarship continues through the Raimundus-Lullus-Institut in Freiburg.", works: [{"title": "Ars generalis ultima (1308)", "note": "Final ternary-phase Art: combinatorial logic of nine divine principles and four figures."}, {"title": "Ars brevis (1308)", "note": "Abridged Art for students; the most circulated Lullian manual of combinatorial letter-principles."}, {"title": "Ars demonstrativa (c. 1283)", "note": "Mature quaternary Art: 12 figures, 16 divine principles (letters B–R); stellar-letter combinatorial system."}, {"title": "Arbor scientiae (1295–96)", "note": "Tree of Science: sixteen trees generating encyclopedic knowledge, mapping cosmos to divine principles."}, {"title": "Liber de secretis naturae seu de quinta essentia", "note": "Pseudo-Lullian alchemical treatise on the fifth essence; influenced Agrippa and Bruno."}] },
  "Arnaldus de Villanova": { wikipediaUrl: "https://en.wikipedia.org/wiki/Arnaldus_de_Villanova", bio: "Arnaldus de Villanova (c. 1240\u20131311), also Arnau de Vilanova, was a physician, diplomat, alchemist, and apocalyptic theologian whose exact birthplace is contested among Villeneuve-l\u00e8s-Maguelone near Montpellier and several towns named Villanueva in Aragon, Catalonia, and Provence. He studied medicine at Montpellier, completing his training around 1260, and served as personal physician to the King of Aragon from 1281; among his patients were three popes and three kings. He taught at the medical school of Montpellier and later led the medical school in Paris between 1291 and 1299, and was the first physician to use alcohol as an antiseptic.\n\nArnaldus translated numerous medical texts from Arabic, including works by Avicenna and Galen, and was influential behind the papal bull of 1309 requiring medical students to demonstrate knowledge of roughly fifteen Greco-Arabic treatises. He was reputed as an alchemist and astrologer: the door of his Montpellier home bore carved depictions of a roaring lion and a dragon biting its own tail, both recognized alchemical symbols, and several prominent alchemists acknowledged him as an adept. However, many alchemical texts attributed to him\u2014including the Rosarius Philosophorum, Novum Lumen, and Flos Florum\u2014are not authentic, and he is listed in scholarship as pseudo-Arnaldus de Villa Nova.\n\nInfluenced by Joachim of Fiore, Arnaldus prophesied in De adventu Antichristi (1288) that the world would end in 1378 with the coming of the Antichrist, and he wrote extensively on church reform in both Latin and Catalan. His reformist and apocalyptic views repeatedly brought him into conflict with ecclesiastical authorities: he was condemned for heresy by the University of Paris in 1299 and imprisoned, saved only by the intervention of Pope Boniface VIII, whom he had cured of illness. He was imprisoned again around 1304 under Pope Benedict XI, the Sorbonne ordered his philosophical works burned, and after his death the inquisitor of Tarragona condemned him and fifteen of his propositions were censured.", works: [{"title": "De adventu Antichristi (1288)", "note": "Joachimite apocalyptic prophecy dating the Antichrist to 1378; brought him heresy charges."}, {"title": "De Vinis", "note": "Medicinal uses of wine and remediation of spoiled wine; first alcohol-as-antiseptic use."}, {"title": "Speculum medicinae", "note": "Major authentic medical work reflecting his Montpellier training and Arabic-Galenic synthesis."}, {"title": "Rosarius Philosophorum (attributed)", "note": "Pseudo-Arnaldian alchemical treatise on the rose of the philosophers; not authentic."}, {"title": "Regimen sanitatis ad regem Aragonum", "note": "Health regimen dedicated to the King of Aragon; a staple of medieval preventive medicine."}] },
  "Moses de Le\u00f3n": { wikipediaUrl: "https://en.wikipedia.org/wiki/Moses_de_Le%C3%B3n", bio: "Moses de Le\u00f3n (c. 1240\u20131305), known in Hebrew as Moshe ben Shem-Tov, was a Spanish rabbi and Kabbalist born around 1240, with his birthplace generally identified as Le\u00f3n in the Kingdom of Le\u00f3n, though an alternative tradition holds he was born in Guadalajara with his surname deriving from his father, Shem-Tov de Le\u00f3n. He spent approximately thirty years in Guadalajara and Vallidolid before relocating to \u00c1vila, where he lived for the remainder of his life, and died in 1305 at Ar\u00e9valo while returning home. He is the figure most renowned for first publicizing the Zohar, the central text of Jewish mysticism, which he claimed to have transcribed from an ancient manuscript attributed to the 2nd-century sage Shimon bar Yochai.\n\nModern scholars believe the Zohar is substantially his own work, despite his assertion of ancient tannaitic provenance, and this pseudepigraphic practice was apparently not isolated: de Le\u00f3n also produced hundreds of pseudepigraphic responsa, commentaries, and Kabbalistic tracts that he falsely attributed to earlier authorities. The Zohar's first edition was printed in Mantua in 1558, over two centuries after his death, and it reshaped Jewish spirituality for centuries. He pioneered the Kabbalistic theory of Biblical interpretation known as Pardes, adapting the medieval Christian fourfold method for Jewish use as an acronym for Peshat (literal), Remez (allegorical), Derash (midrashic), and Sod (esoteric) levels of meaning, a framework that became foundational to subsequent Kabbalistic hermeneutics.\n\nDe Le\u00f3n occupies a complex position in Jewish intellectual history, simultaneously a forger and one of the most influential mystical authors ever to write in Hebrew. His Zohar is one of history's most consequential pseudepigrapha, and its doctrines of the sefirot, the divine names, and the cosmic significance of Hebrew letters became the backbone of later Kabbalah, including the stellar-letter correspondences central to works such as the Sefer Raziel tradition.", works: [{"title": "The Zohar", "note": "Central text of Kabbalah; presented as tannaitic but by de León. Foundation of sefirot and letter mysticism."}, {"title": "Sefer ha-Rimon", "note": "One of his few works openly composed under his own name; a Kabbalistic treatise in Hebrew."}, {"title": "Sefer Mishkan ha-Edut", "note": "Kabbalistic work on the tabernacle of testimony; edited by Avishai Bar Asher (Cherub Press, 2013)."}, {"title": "Pardes (fourfold exegesis)", "note": "Peshat/Remez/Derash/Sod hermeneutic framework; foundation of later Kabbalistic Bible interpretation."}] },
  "Cecco d'Ascoli": { wikipediaUrl: "https://en.wikipedia.org/wiki/Cecco_d%27Ascoli", bio: "Cecco d'Ascoli (1257\u20131327), born Francesco degli Stabili in Folignano near Ascoli, was a medieval Italian physician, astrologer, and poet who devoted himself to mathematics and astrology and secured a professorship in astrology at the University of Bologna in 1322. His byname \"Cecco\" is a diminutive of Francesco, and \"Ascoli\" marks his birthplace. He published a commentary on the Sphere of John de Sacrobosco in which he advanced audacious theories concerning the employment and agency of demons, bringing him into conflict with ecclesiastical authorities and resulting in a 1324 sentence of fasts, prayers, and a fine of seventy crowns.\n\nAfter fleeing to Florence, Cecco joined the household of Carlo di Calabria, but his confrontational nature and what contemporaries called pseudo-science and plain speaking made him many enemies. He had publicly criticized Dante's Commedia and Guido Cavalcanti's Canzone d'amore, and the physician Dino del Garbo pursued him relentlessly, reviving the earlier charge of impiety. Cecco was retried for relapse into heresy and burned at Florence on 26 September 1327, the day after sentencing, at roughly seventy years of age.\n\nHis most significant work is the Acerba, an encyclopedic poem in sesta rima (six-line stanzas) that served as a compendium of contemporary natural science, covering celestial influences, animal properties, precious stones, meteorological phenomena, earthquakes, and moral philosophy across four books on astronomy and meteorology, astrology and physiognomy, minerals and animal behavior, and moral and physical problems. The Acerba reflects the medieval worldview in which celestial mechanics, earthly phenomena, and moral philosophy were understood as interconnected domains\u2014the same stellar-influence framework that underpins the occult sciences and the letter-planet correspondences of later Renaissance magic. A lunar crater, Cichus, bears his name, commemorating his contributions to medieval astronomy and astrology.", works: [{"title": "Acerba", "note": "Encyclopedic sesta-rima poem on astrology, stones, animals, meteorology; celestial influence lore."}, {"title": "Commentary on the Sphere of Sacrobosco", "note": "Commentary on demons' agency over celestial spheres; triggered his 1324 heresy sentence."}] },
  "Marsilio Ficino": { wikipediaUrl: "https://en.wikipedia.org/wiki/Marsilio_Ficino", bio: "Marsilio Ficino (19 October 1433 \u2013 1 October 1499) was an Italian scholar, Catholic priest, and physician born in Figline Valdarno in the Republic of Florence, where his father Diotifeci d'Agnolo served as a physician under Cosimo de' Medici, who became Ficino's lifelong patron. Cosimo chose Ficino to head his refounded Platonic Academy at Florence, an institution modeled on Plato's ancient Academy, and in 1462 provided him with Greek manuscripts of Plato's works; Ficino undertook the first complete Latin translation of Plato's extant corpus, finishing the draft by 1468\u201369 and publishing it in 1484, making Plato systematically accessible to Western European scholars for the first time. He also translated numerous Neoplatonic authors including Plotinus, Porphyry, and Iamblichus, and his students included Giovanni Pico della Mirandola and Francesco Cattani da Diacceto.\n\nFicino produced the first Latin translation of the Corpus Hermeticum in 1471, a collection of Hellenistic Greek documents discovered by Leonardo da Pistoia, placing him at the forefront of Renaissance Hermeticism, and his interest in astrology and the integration of cosmic influences with human life is most fully developed in De vita libri tres (1489). His Neoplatonist worldview embraced the concept of the anima mundi, the world's ensoulment, and he articulated the concept of prisca theologia, the idea of an ancient theological wisdom linking pagan sages such as Hermes Trismegistus and Plato to Christian truth. In 1489 he was accused of heresy before Pope Innocent VIII because the third book of De vita contained specific instructions on healthful living in a world of demons and other spirits, but he was ultimately acquitted.\n\nFicino coined the term \"Platonic love,\" which first appeared in a 1476 letter to Alamanno Donati, and his 1492 Epistulae contained Platonic love letters to his friend Giovanni Cavalcanti, popularizing the concept across Western Europe. In his later commentary on Plotinus's Ennead III, he systematically repudiated key Neoplatonic doctrines\u2014the transmigration of the soul, the soul's eternity, and intermediary creation\u2014reinterpreting them as moral allegories to reconcile Platonism with Christianity. His translations of Plato, the Hermetica, and the Neoplatonists fundamentally reshaped Renaissance intellectual culture and laid groundwork for centuries of European philosophical development, influencing figures such as Paracelsus.", works: [{"title": "Theologia Platonica de immortalitate animae (1482)", "note": "Treatise on soul's immortality synthesizing Plato and Christianity; cornerstone of Renaissance Neoplatonism."}, {"title": "De vita libri tres (1489)", "note": "Three books on life with medical-astrological advice and planetary talismans; drew 1489 heresy charges."}, {"title": "Latin translation of the Corpus Hermeticum (1471)", "note": "First Latin Hermetica; launched Renaissance Hermeticism and prisca theologia."}, {"title": "De amore (1484)", "note": "Commentary on Plato's Symposium; develops Platonic love and celestial ascent."}, {"title": "Commentary on Plotinus's Enneads", "note": "Latin Plotinus with commentary; recast Neoplatonic cosmic hierarchies as Christian moral allegory."}] },
  "Johannes Trithemius": { wikipediaUrl: "https://en.wikipedia.org/wiki/Johannes_Trithemius", bio: "Johannes Trithemius, born Johann Heidenberg on 1 February 1462 in Trittenheim on the Moselle River in the Electorate of Trier, was a German Benedictine abbot, historian, cryptographer, and occultist whose byname derives from his native town. His father died in his infancy and his stepfather was hostile to education, forcing him to study Greek, Latin, and Hebrew in secret and with many difficulties; at seventeen he left home for teachers, traveling through Trier, Cologne, the Netherlands, and Heidelberg. In 1482, caught in a snowstorm, he took shelter at the Benedictine abbey of Sponheim and decided to remain, and was elected abbot in 1483 at just twenty-one, transforming the neglected abbey into a center of learning by expanding its library from around fifty items to more than two thousand.\n\nTrithemius is considered a founder of modern cryptography (alongside Leon Battista Alberti) and of steganography, as well as a progenitor of bibliography and literary studies as organized disciplines, and he had considerable influence on the development of early modern and modern occultism. His notable students included Heinrich Cornelius Agrippa and Paracelsus, and his reputation as a necromancer intertwined with the Faust legend: he was the first author to mention the historical Doctor Faustus in a 1507 account, and Martin Luther later wrote of a magician understood to be Trithemius who summoned Alexander the Great and the emperor's deceased wife Mary of Burgundy to entertain Maximilian. Increasing tensions at Sponheim, partly due to his reputation as a magician, led to his resignation in 1506, after which he became abbot of St. James's Abbey (the Schottenkloster) in W\u00fcrzburg under Bishop Lorenz von Bibra, remaining there until his death on 13 December 1516.\n\nAs a historian Trithemius produced chronicles of Sponheim and Hirsau Abbey distinguished by Latin mastery and eloquent prose, but he inserted several fictional passages and invented entire sources, most notoriously Hunibald, a supposedly Scythian historian used to establish Trojan origins for the Franks in service of Habsburg dynastic politics. His most famous work, the Steganographia (written c. 1499, published 1606), appears to treat magic and spirit communication over long distances, but its first two volumes were revealed as cryptographic and steganographic content after the 1606 publication of a decryption key, and the third volume was shown in the 1990s to conceal further cryptographic material beneath its magical formulae. The book was placed on the Index Librorum Prohibitorum in 1609 and removed in 1900, and it contains the Ave Maria cipher, where each coded letter is replaced by a short Latin sentence about Jesus.", works: [{"title": "Steganographia (c. 1499; pub. 1606)", "note": "Apparent spirit-magic treatise that is actually cryptography; Ave Maria cipher. Indexed 1609."}, {"title": "Polygraphia (written 1508; pub. 1518)", "note": "First printed book on cryptography; frames ciphering as a consequent of God-empowered soul ascent."}, {"title": "De septem secundeis (c. 1508)", "note": "World history governed by seven planetary intelligences moving the orbs; astrological occult chronology."}, {"title": "Annales Hirsaugienses (1509–1514)", "note": "1,400-page chronicle of France and Germany; among the first humanist histories."}, {"title": "Liber de scriptoribus ecclesiasticis (1494)", "note": "Bibliographical work on ecclesiastical writers; a founding text of bibliography as a discipline."}] },
  "Giovanni Pico della Mirandola": { wikipediaUrl: "https://en.wikipedia.org/wiki/Giovanni_Pico_della_Mirandola", bio: "Giovanni Pico della Mirandola (1463\u20131494) was an Italian Renaissance nobleman and philosopher, widely regarded as the founder of Christian Kabbalah. Born to the lords of Mirandola, he was a precocious child named a papal protonotary at age ten, and studied canon law at Bologna, philosophy at Ferrara and Padua, and at Paris. At Padua he studied Hebrew and Arabic with the Jewish Averroist Elia del Medigo, who translated kabbalistic manuscripts into Latin for him, and his tutor in Kabbalah, Rabbi Yohanan Alemanno, taught that magic was the final stage of intellectual and spiritual education.\n\nIn December 1486 Pico published his 900 Theses\u2014propositions spanning Platonism, Aristotelianism, Hermeticism, and Kabbalah\u2014and offered to fund a public debate in Rome. Pope Innocent VIII halted the debate, appointed a commission, and condemned all 900 theses, making it the first printed book universally banned by the Church; Pico fled, was imprisoned, and was only cleared in 1493 under Alexander VI. His syncretic program held that different religious traditions describe the same God in different words, and he relied on translations by the convert Flavius Mithridates, who supplied doctored kabbalistic texts.\n\nPico died in 1494 at age 31 under mysterious circumstances alongside his friend Poliziano; a 2007 forensic exhumation indicated arsenic poisoning. In his final years he became a follower of Savonarola, destroyed his poetry, and gave away his fortune. His Oration on the Dignity of Man was later dubbed the \"Manifesto of the Renaissance,\" and his posthumous Disputationes against predictive astrology shaped early modern critiques of judicial astrology.", works: [{"title": "Oration on the Dignity of Man (1486)", "note": "Manifesto of the Renaissance; introduced the 900 theses, framing human vocation as mystical ascent."}, {"title": "900 Theses / Conclusiones (1486)", "note": "900 propositions blending Platonism, Kabbalah, Hermeticism; first printed book banned by the Church."}, {"title": "Heptaplus (1489)", "note": "Mystical-allegorical reading of Genesis through seven biblical senses; all religions describe the same God."}, {"title": "De Ente et Uno / On Being and the One (1491)", "note": "Attempted reconciliation of Platonic and Aristotelian metaphysics of being and the one."}, {"title": "Disputationes adversus astrologiam divinatricem", "note": "Posthumous treatise against deterministic judicial astrology; defends free will vs stellar determinism."}] },
  "Heinrich Cornelius Agrippa": { wikipediaUrl: "https://en.wikipedia.org/wiki/Heinrich_Cornelius_Agrippa", bio: "Heinrich Cornelius Agrippa von Nettesheim (1486\u20131535) was a German Renaissance polymath, occult philosopher, and soldier whose Three Books of Occult Philosophy became the foundational summa of early modern Western esotericism. Born near Cologne into minor nobility, he matriculated at the University of Cologne at thirteen and earned his magister artium by 1502, where the Albertist faction sparked his interest in the occult; he later studied in Paris and reportedly joined a secret occult society. He served as a mercenary captain under Emperor Maximilian I, who granted him the title of Ritter.\n\nUnder the patronage of Margaret of Austria, Agrippa lectured at the University of Dole on Reuchlin's De verbo mirifico and wrote a cabalistic defense of women's superiority, for which he was denounced as a \"Judaizing heretic\" and forced to leave in 1510. He then studied with the humanist abbot Trithemius at W\u00fcrzburg, to whom he dedicated an early draft of De occulta philosophia; Trithemius advised him to keep his occult studies secret. In Italy (1511\u20131518) he encountered kabbalistic and Hermetic ideas descended from Ficino and Pico, and lectured at Pavia on the Pimander of Hermes Trismegistus.\n\nAgrippa's mature system synthesized Kabbalah, Hermeticism, and Neoplatonism, arguing that the natural, celestial, and divine realms interconnect through Neoplatonic participation and that magic is ultimately sourced from God. His apparent recantation in De vanitate is now read as an admission of limits rather than a global retraction. He died in Grenoble in 1535 after being arrested by order of Francis I for disparaging the queen-mother, leaving a large family from three marriages.", works: [{"title": "De occulta philosophia libri tres (1531/1533)", "note": "Magnum opus; synthesizes Kabbalah, Hermeticism, Neoplatonism across elemental, celestial, divine realms."}, {"title": "De incertitudine et vanitate scientiarum (1526/1527)", "note": "Skeptical fideist satire on the sciences; influenced Montaigne, Descartes, Goethe."}, {"title": "Declamatio de nobilitate et praecellentia foeminei sexus (1529)", "note": "Cabalistically argued theological and moral superiority of women; early feminist occult tract."}, {"title": "Spurious Fourth Book of Occult Philosophy (1559)", "note": "Ritual magic compilation attributed to Agrippa but not his; circulated widely as an appendix."}] },
  "Paracelsus": { wikipediaUrl: "https://en.wikipedia.org/wiki/Paracelsus", bio: "Paracelsus, born Theophrastus Bombast von Hohenheim (c. 1493\u20131541), was a Swiss-German physician, alchemist, and mystic whose Paracelsianism movement reshaped early modern medicine. Educated by his chemist-physician father in botany, mineralogy, mining, and natural philosophy, and by clerics at St Paul's Abbey, he earned his M.D. from the University of Ferrara in 1515/16. Between 1517 and 1524 he traveled extensively across Europe and the Near East as an army surgeon, gathering folk and alchemical knowledge.\n\nAs city physician in Basel (1527) he lectured in German rather than Latin and publicly burned the works of Galen and Avicenna, an iconoclastic gesture that forced him to flee in 1528 and resume an itinerant life. He pioneered the medical use of chemicals and minerals, likely first naming zinc (~1526) and unknowingly observing hydrogen, and he rejected Galenic humoral theory in favor of the tria prima\u2014sulphur (combustibility/soul), mercury (liquidity/spirit), and salt (stability/body)\u2014explaining disease as their imbalance. He articulated the dose-response principle, \"Solely the dose determines that a thing is not a poison,\" earning him the title father of toxicology.\n\nParacelsus was deeply influenced by Hermetic, Neoplatonic, and Pythagorean philosophies, and treated astrology as central to medical practice, devoting sections of his writings to astrological talismans for curing disease. His Astronomia magna (completed 1537, published 1571) was a treatise on hermeticism, astrology, divination, theology, and demonology that established his reputation as a prophet, and he described four elemental beings\u2014Salamanders, Gnomes, Undines, and Sylphs\u2014linking the macrocosm to the human microcosm. He died in Salzburg in 1541.", works: [{"title": "Opus Paramirum (1531)", "note": "First exposition of the tria prima (sulphur, mercury, salt) replacing Galenic humors; Paracelsian medicine."}, {"title": "Astronomia magna / Philosophia sagax (1537; pub. 1571)", "note": "Treatise on Hermeticism, astrology, divination, demonology; cast Paracelsus as a prophet."}, {"title": "Die grosse Wundartznei (1536)", "note": "The Great Surgery Book; restored his reputation with practical wound care and antisepsis principles."}, {"title": "Von der Bergsucht / On the Miners' Sickness (1534)", "note": "First systematic study of occupational disease; linked mineral/planetary influences to miners' ailments."}, {"title": "A Book on Nymphs, Sylphs, Pygmies, and Salamanders (posthumous)", "note": "Four elemental beings tied to classical elements; Hermetic cosmology of stellar-elemental forces."}] },
  "Nostradamus": { wikipediaUrl: "https://en.wikipedia.org/wiki/Nostradamus", bio: "Michel de Nostredame (1503\u20131566), known as Nostradamus, was a French physician, astrologer, and prognosticator whose Les Proph\u00e9ties became one of the most widely published and commented prophetic works in European history. Born in Saint-R\u00e9my-de-Provence to a family of recent Jewish converts to Catholicism, he studied at the University of Avignon until a plague outbreak closed it, then spent eight years traveling the countryside researching herbal remedies. He entered the University of Montpellier in 1529 to pursue a medical doctorate but was expelled when his prior apothecary work\u2014a manual trade forbidden by statute\u2014was discovered.\n\nAfter losing his first wife and two children to plague in 1534, he worked as a plague physician in Marseille, Salon-de-Provence, and Aix-en-Provence, and in 1547 settled in Salon and married wealthy widow Anne Ponsarde. From 1550 he shifted from medicine toward the occult, publishing annual almanacs\u2014his most popular works, containing at least 6,338 prophecies\u2014and Latinizing his name to Nostradamus. Catherine de' Medici became his foremost patron, summoning him to Paris and making him Counselor and Physician-in-Ordinary to King Charles IX.\n\nHis prophetic method relied on judicial astrology and comparative horoscopy, but scholarship shows he paraphrased collections of ancient end-of-world prophecies, particularly the Mirabilis Liber (1522), supplemented with historical sources like Livy, Suetonius, and Plutarch. He explicitly rejected the label \"prophet.\" Over 200 editions of Les Proph\u00e9ties have appeared with over 2,000 commentaries, though academic sources reject any genuine supernatural ability, noting the quatrains are characteristically vague and that associations with world events result from misinterpretations or mistranslations. He died in 1566 after years of gout and edema.", works: [{"title": "Les Prophéties (1555; omnibus 1568)", "note": "942 quatrains in ten Centuries predicting wars, plagues, disasters; most commented prophetic work in history."}, {"title": "Almanacs (1550–1566)", "note": "Annual prognostications, his most popular works; 6,338+ prophecies grounded in judicial astrology."}, {"title": "Traité des fardemens", "note": "Medical cookbook on plague treatment and cosmetic preparations; bridges physician work with apothecary past."}, {"title": "Orus Apollo (manuscript)", "note": "Purported translation of a Greek work on Egyptian hieroglyphs; ties prophecy to hieroglyphic mysticism."}, {"title": "Paraphrase de C. GALIEN", "note": "Free paraphrase of Galen's Protreptic; shows his medical-humanist grounding before the turn to prophecy."}] },
  "John Dee": { wikipediaUrl: "https://en.wikipedia.org/wiki/John_Dee", bio: "John Dee (1527\u20131608/09) was an English mathematician, astronomer, astrologer, and occult philosopher who served as court astronomer and advisor to Elizabeth I and became the founding figure of Enochian angelic magic. Of Welsh descent, he entered St John's College, Cambridge in 1542, became an original fellow of Trinity College on its 1546 founding, and studied at Leuven under Gerardus Mercator and Gemma Frisius, befriending Abraham Ortelius. He advised on navigation, trained voyagers for North American exploration, and is credited with coining the term \"British Empire.\"\n\nA devout Christian influenced by Hermetic, Platonic, and Pythagorean systems, Dee believed numbers were the basis of all things and that humans could exercise divine power through mathematics; his goal was a unified world religion healing the Catholic-Protestant schism. He served as court astronomer, chose Elizabeth I's coronation date, and was arrested in 1555 for casting horoscopes of Mary I and Princess Elizabeth before being exonerated. He advised on calendar reform in 1583, recommending England accept the Gregorian calendar with eleven days rather than ten.\n\nBy the early 1580s, dissatisfied with natural philosophy, Dee turned to supernatural means, meeting scryer Edward Kelley in 1582 and conducting \"spiritual conferences\" performed with intense Christian piety after purification, prayer, and fasting. Angels allegedly dictated books through Kelley in a special angelic or Enochian language, founding Enochian magic; in 1587 Kelley claimed the angel Uriel ordered them to share wives, after which Dee broke off the conferences and returned to England in 1589. He spent his final years in poverty at Mortlake, dying late 1608 or early 1609 aged 81 with no known grave.", works: [{"title": "Monas Hieroglyphica (1564)", "note": "Hermetic-Kabbalistic glyph expressing mystical unity of creation; includes a cryptography treatise."}, {"title": "Mathematical Preface to Euclid's Elements (1570)", "note": "Argued mathematics underpins all arts and sciences; his most widely influential work, in English."}, {"title": "General and Rare Memorials pertayning to the Perfect Arte of Navigation (1577)", "note": "Vision of a maritime empire; frontispiece of Britannia kneeling before Elizabeth I."}, {"title": "De Heptarchia Mystica (1582–83)", "note": "Mystical Rule of the Seven Planets; angelic communications tying planetary spirits to stellar governance."}, {"title": "Mysteriorum Libri Quinque / A True & Faithful Relation (pub. 1659)", "note": "Records of angelic conferences with Kelley; foundation of Enochian magic and the angelic-language project."}] },
  "Felipe II of Spain": { wikipediaUrl: "https://en.wikipedia.org/wiki/Philip_II_of_Spain", bio: "Philip II of Spain (1527\u20131598), called \"the Prudent,\" was a Habsburg monarch who ruled the most extensive empire in the world, including Spain, Naples, Sicily, Portugal (from 1580, forming the Iberian Union), the Netherlands, and\u2014jure uxoris with Mary I\u2014England and Ireland (1554\u20131558). Born in Valladolid to Emperor Charles V and Isabella of Portugal, he was tutored by humanists including the future Archbishop Sil\u00edceo and began governing as regent at sixteen, having been made Duke of Milan in 1540. He saw himself as the defender of Catholic Europe against the Ottoman Empire and the Protestant Reformation.\n\nHis reign was defined by the decisive naval victory at Lepanto (1571) against the Ottomans, the brutal repression of the Dutch revolt in the Eighty Years' War, the failed Spanish Armadas against England (1588, 1596, 1597), and intervention in the French Wars of Religion through the Catholic League. He ordered the expulsion of Moriscos from Granada after the 1569 revolt, defaulted on loans repeatedly (1557, 1560, 1569, 1575, 1596), and moved his court to Madrid in 1561, making it the permanent capital. The Philippine Islands were named in his honor, and the Spanish Golden Age flourished in literature, music, and the visual arts under his patronage.\n\nPhilip died at El Escorial in 1598 and was buried in the palace-monastery he had built. The Wikipedia article provides no documented connection to astrology, the occult, stellar symbolism, or kabbalistic/mystical interests; El Escorial is framed solely as a Catholic palace-monastery-pantheon monument to Spain's role as a centre of the Christian world, and he prohibited biographical accounts of his life, contributing to an enigmatic reputation but with no documented private esoteric practice.", works: [{"title": "El Escorial (completed 1584)", "note": "Palace-monastery-pantheon monument to Spain as centre of the Christian world; no documented esoteric program."}, {"title": "Battle of Lepanto (1571)", "note": "Decisive Holy League naval victory over the Ottomans under his half-brother John of Austria."}, {"title": "Move of the court to Madrid (1561)", "note": "Established Madrid as the permanent Spanish capital, centralizing Habsburg imperial governance."}, {"title": "Relaciones geográficas", "note": "Extensive questionnaires to New World towns; systematic geographic and ethnographic governance."}, {"title": "Iberian Union (1580)", "note": "Personal union of Spain and Portugal; created the largest European empire of the era and a global domain."}] },
};
